            'firewall' => '🔥 Firewall',        
			'upgrade_firewall' => 'Ontgrendel een krachtige beveiligingsfirewall die je WordPress-website in realtime beschermt tegen de meest voorkomende dreigingen. De Pro-versie bevat 9 exclusieve beschermingslagen die al het bezoek analyseren en automatisch pogingen tot datadiefstal, kwaadaardige code-injecties, bots, kwetsbaarheidsscanners, Brute Force-aanvallen en verkeersmisbruik blokkeren voordat ze je website kunnen raken.',
			'upgrade_hardening'  => 'De Pro-versie bevat 12 exclusieve beveiligingsschilden die zijn ontworpen om je WordPress-installatie te versterken vanaf de interne configuratie. Ontgrendel geavanceerde functies die gevoelige informatie verbergen, kwetsbare functies uitschakelen, de meest gebruikte aanvalskanalen van hackers en bots blokkeren, kritieke systeembestanden beschermen en de uitvoering van kwaadaardige code voorkomen om je website een stuk veiliger te houden.',
			'upgrade_database'  => 'De Pro-versie bevat geavanceerde beheer- en beveiligingshulpmiddelen voor je database rechtstreeks vanuit het controlepaneel. Wijzig veilig het voorvoegsel van je tabellen om de structuur van je site te verbergen voor geautomatiseerde SQL-injectieaanvallen, een van de meest misbruikte kwetsbaarheden door hackers.
									Daarnaast kun je met één klik de database direct naar je computer downloaden, zodat je altijd een lokale back-up bij de hand hebt voor noodgevallen of een snelle herstelactie.',
			'upgrade_404' => 'Met de Pro-versie kun je een aangepaste 404-pagina activeren die door de plugin is gemaakt. Hiermee vervang je de generieke foutpagina van je thema om een professionelere en consistentere ervaring met je website te bieden.
								Pas elk detail eenvoudig aan: bepaal de hoofdtitel die de gebruiker te zien krijgt en voeg een aangepast foutbericht toe om de bezoeker duidelijk over het probleem te informeren. Bovendien heb je de optie om een afbeelding toe te voegen, zoals je merklogo of een afbeelding naar keuze, zodat de visuele identiteit van je site behouden blijft, zelfs bij een gebroken link.',
			'upgrade_cambiourl' => ' Met de Pro-versie kun je de inlog-URL van je controlepaneel aanpassen. Hiermee verberg je het traditionele WordPress-adres om je site te beschermen tegen Brute Force-aanvallen en geautomatiseerde bots.
									Stel een nieuw aangepast webadres in door hetwoord of de tekst van je voorkeur in te voeren (bijvoorbeeld toegang of mijn-geheime-login), zodat je nieuwe toegangspunt volledig veilig en privé is.',
			'upgrade_cleanup' => ' De Pro-versie bevat een krachtige onderhouds- en opschoontool die is ontworpen om wees-elementen en tijdelijke bestanden op te schonen, wat de prestaties van de SQL-queries op je website aanzienlijk verbetert.
									Optimaliseer je database door oude automatische opslaggeschiedenis te verwijderen via het opschonen van post-revisies, ruimte vrij te maken door als spam gemarkeerde reacties te verwijderen, en de algehele snelheid te verbeteren door verlopen transients en verouderde caches in de optietabel op te schonen. ' ,
			'upgrade_security' => 'De Pro-versie bevat een geavanceerd Brute Force-controlesysteem en toegangsmonitor om de ingang van je website te beschermen tegen indringers en geautomatiseerde aanvallen.
									Stel slimme beveiligingen in door een drempelwaarde voor mislukte pogingen te definiëren die het maximum aantal toegestane fouten bepaalt voordat een IP tijdelijk wordt geblokkeerd, en stel de duur van de straf in minuten in.
									Daarnaast heb je absolute controle dankzij het gedetailleerde toegangslogboek, waarin je precies kunt zien welke gebruiker heeft ingelogd, de dag, datum en tijd, en vanaf welk IP-adres. Als je een patroon of verdachte verbinding ontdekt, kun je het IP-adres direct blokkeren of toevoegen aan de handmatige zwarte lijst om de toegang permanent te weigeren.',
			      
