            'headers_intro' => 'Administre e ative as camadas de segurança baseadas em cabeçalhos HTTP. Defina os níveis de proteção para mitigar vulnerabilidades e garantir uma navegação encriptada e privada.',
            'layer_1_title' => 'Anti-Clickjacking',
            'layer_1_desc' => 'Proteção contra iframes maliciosos: Evitamos que páginas externas possam carregar o seu site dentro de molduras ocultas, protegendo os utilizadores contra técnicas de engano como o sequestro de cliques (clickjacking). DENY bloqueia por completo que o seu site possa ser exibido dentro de outra página, enquanto que SAMEORIGIN apenas permite que o faça o seu próprio site.',
