            'layer_4_title' => 'Referrer Policy',
            'layer_4_desc' => 'Controlo de metadados: Evita que ao clicar em links externos se filtre informação confidencial sobre a página de origem através do cabeçalho Referer. No-Referrer (Privacidade total): Oculta por completo a procedência da visita, impedindo que a página de destino saiba a partir de que link chegou.
            Strict Origin When Cross-Origin: Partilha apenas o domínio de origem ao navegar para sites externos, mantendo a privacidade das rotas internas.',
