            'layer_5_desc' => 'Força o carregamento seguro: Obriga o navegador a descarregar todos os recursos do site (como imagens, scripts e estilos) exclusivamente através de conexões encriptadas (HTTPS), bloqueando qualquer conteúdo inseguro.',
