            'hard_file_desc' => 'Impede que se possam modificar os ficheiros do design e dos plugins diretamente a partir do painel de controlo. Esta é uma medida de precaução vital: se alguém conseguisse adivinhar a sua password de administrador, não poderia injetar vírus nem código malicioso dentro dos ficheiros do seu site.',
