            'hard_xml_desc' => 'Desativa uma porta antiga do WordPress que já quase não se utiliza, mas que os piratas informáticos aproveitam constantemente para realizar ataques automatizados massivos, tentando adivinhar passwords testando milhares de combinações por segundo.',
