            'hard_enum_title' => 'Ocultar Nomes de Utilizador',
            'hard_enum_label' => 'Bloquear o rastreio de autores nos endereços web',
            'hard_enum_desc' => 'Evita que qualquer pessoa ou programa espião possa averiguar facilmente os nomes de utilizador reais com os quais entra para administrar a página, protegendo-o contra tentativas de usurpação e ataques de força bruta.',
